        defaults: () => ({
            body: 0,
            kind: ShapeKind.Hull,
            geometry: 0,
            sphereCenter: [0, 0, 0],
            capsuleCenter1: [0, -0.5, 0],
            capsuleCenter2: [0, 0.5, 0],
            radius: 0.5,
            scale: [1, 1, 1],
            hullPosition: [0, 0, 0],
            enableHullTransform: 0,
