import {
    Body,
    BodyType,
    Camera,
    component,
    DirectionalLight,
    GlobalAmbientLight,
    Hulls,
    lookAtRotation,
    Materials,
    MeshInstance,
    MeshMaterial,
    type Plugin,
    Shape,
    StandardMaterial,
    StandardRenderer,
    Transform,
    type World,
} from "@dylanebert/shallot";
import { Orbit, OrbitPlugin } from "@dylanebert/shallot/extras";
import { StandardPhysicsPlugin } from "@dylanebert/shallot/standard/physics";

/** Marks the dropped box. */
export const FallingBox = component("FallingBox", {});
/** Marks the floor it lands on. */
export const Floor = component("Floor", {});

/** Height of the box's center when it is released, in meters. */
export const DROP_HEIGHT = 5;
/** Floor width and depth in meters; its top face sits at y = 0. */
export const FLOOR_SIZE = 12;

export const BLUE = [0.05, 0.25, 0.9, 1] as const;
export const GRAY = [0.45, 0.45, 0.45, 1] as const;

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xffffff;
    ambient.brightness = 400;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.6) });
    world.add(sun, DirectionalLight, { color: 0xffffff, illuminance: 6000 });
    world.storage(DirectionalLight).shadowMapsEnabled.set(sun, 1);

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x1b1d22 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 12, yaw: 0.6, pitch: 0.3, pan: [0, 2, 0] });
    world.add(camera, Transform);

    // One unit-cube hull serves both bodies; each Transform.scale sizes its collider and
    // the built-in unit-cube mesh together, so what you see is what collides.
    const unitBox = world.resource(Hulls).add({ name: "unit box", halfExtents: [0.5, 0.5, 0.5] });
    const materials = world.resource(Materials);

    const floor = world.create();
    world.add(floor, Transform, {
        translation: [0, -0.5, 0],
        scale: [FLOOR_SIZE, 1, FLOOR_SIZE],
    });
    world.add(floor, Body, { type: BodyType.Static });
    world.add(floor, Shape, { geometry: unitBox });
    world.add(floor, MeshInstance);
    world.add(
        floor,
        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: [...GRAY], perceptualRoughness: 0.9 })),
    );
    world.add(floor, Floor);

    const box = world.create();
    world.add(box, Transform, {
        translation: [0, DROP_HEIGHT, 0],
        // A slight tilt so it lands on an edge and settles flat.
        rotation: [0.08, 0.2, 0.12, 0.969],
    });
    world.add(box, Body, { type: BodyType.Dynamic });
    world.add(box, Shape, { geometry: unitBox });
    world.add(box, MeshInstance);
    world.add(
        box,
        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: [...BLUE], perceptualRoughness: 0.5 })),
    );
    world.add(box, FallingBox);
}

export const FallingBoxDemo: Plugin = {
    name: "FallingBoxDemo",
    components: [FallingBox, Floor],
    dependencies: [StandardPhysicsPlugin, OrbitPlugin],
    initialize: makeScene,
};

