import { expect, setDefaultTimeout, test } from "bun:test";
import { createApp, MeshMaterial, Materials, Sleeping, Transform } from "@dylanebert/shallot";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import { BLUE, DROP_HEIGHT, FallingBox, FallingBoxDemo, Floor, GRAY } from "./index";

setDefaultTimeout(TIMEOUT.node);

test("the box falls on its own, lands on the floor and comes to rest", async () => {
    const app = await createApp({ defaults: false, plugins: [FallingBoxDemo] });
    try {
        const world = app.world;
        const box = [...world.query([FallingBox])][0]!;
        const y = () => world.storage(Transform).translation.y.get(box);
        expect(y()).toBeCloseTo(DROP_HEIGHT);

        let lowest = Infinity;
        let fell = false;
        for (let i = 0; i < 60 * 10 && !world.has(box, Sleeping); i++) {
            world.tick();
            lowest = Math.min(lowest, y());
            if (y() < DROP_HEIGHT - 1) fell = true;
        }
        expect(fell).toBe(true);
        expect(world.has(box, Sleeping)).toBe(true);
        // Resting on a face: half-extent 0.5 above the floor's top at y = 0, not through it.
        expect(y()).toBeCloseTo(0.5, 1);
        expect(lowest).toBeGreaterThan(0.4);
        const [x, , z] = world.get(box, Transform)!.translation;
        expect(Math.hypot(x, z)).toBeLessThan(3);
    } finally {
        app.dispose();
    }
});

test("the box is solid blue and the floor plain gray", async () => {
    const app = await createApp({ defaults: false, plugins: [FallingBoxDemo] });
    try {
        const world = app.world;
        const color = (tag: typeof FallingBox) => {
            const eid = [...world.query([tag])][0]!;
            const material = world.resource(Materials).get(world.get(eid, MeshMaterial)!) as {
                baseColor: ArrayLike<number>;
            };
            return Array.from(material.baseColor);
        };
        expect(color(FallingBox)).toEqual(BLUE.map(Math.fround));
        expect(color(Floor)).toEqual(GRAY.map(Math.fround));
    } finally {
        app.dispose();
    }
});

