import { pipelineWarnings, TIMEOUT } from "@dylanebert/shallot/testing";
import { expect, type Page, test } from "playwright/test";

test.use(pipelineWarnings);

/** Counts strongly blue pixels (the box) and neutral gray pixels (the floor) in the canvas. */
async function colorCounts(page: Page) {
    const screenshot = await page.locator("#canvas").screenshot();
    return page.evaluate(async (base64) => {
        const image = await createImageBitmap(
            new Blob([Uint8Array.from(atob(base64), (value) => value.charCodeAt(0))]),
        );
        const canvas = document.createElement("canvas");
        canvas.width = image.width;
        canvas.height = image.height;
        const context = canvas.getContext("2d")!;
        context.drawImage(image, 0, 0);
        const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
        let blue = 0;
        let gray = 0;
        let blueY = 0;
        for (let i = 0; i < pixels.length; i += 4) {
            const [r, g, b] = [pixels[i]!, pixels[i + 1]!, pixels[i + 2]!];
            if (b > 80 && b > r * 1.8 && b > g * 1.4) {
                blue++;
                blueY += Math.floor(i / 4 / canvas.width);
            } else if (r > 60 && Math.abs(r - g) < 12 && Math.abs(g - b) < 12) gray++;
        }
        return { blue, gray, blueY: blue ? blueY / blue / canvas.height : 0 };
    }, screenshot.toString("base64"));
}

test("the blue box drops onto the gray floor without input and stays there", async ({ page }) => {
    page.on("pageerror", (error) => {
        throw error;
    });
    await page.goto("/");
    await expect(page.locator("body > [data-shallot-loading]")).toHaveCount(0, {
        timeout: TIMEOUT.browser,
    });
    await expect.poll(async () => (await colorCounts(page)).blue).toBeGreaterThan(200);
    const early = await colorCounts(page);
    await page.waitForTimeout(5000);
    const settled = await colorCounts(page);
    if (process.env.SHALLOT_CAPTURE_DIR)
        await page.screenshot({ path: `${process.env.SHALLOT_CAPTURE_DIR}/settled.png` });
    expect(settled.gray).toBeGreaterThan(1000);
    expect(settled.blue).toBeGreaterThan(200);
    // Lower on screen once landed than while it was still up in the air.
    expect(settled.blueY).toBeGreaterThan(early.blueY);
    await page.waitForTimeout(1000);
    const later = await colorCounts(page);
    expect(Math.abs(later.blueY - settled.blueY)).toBeLessThan(0.01);
});
